// Helper: fetch+decrypt a server's root password from the nxeon DB and run a
// command (or interactive-style single command) over ssh2. Mirrors lib/sftp.ts +
// lib/ssh-exec.ts. NEVER echoes the password.
//
// Usage: node sshrun.mjs <serverId> <expectedIp> <<'CMD'
//   ... remote shell command(s) ...
// CMD
import { createDecipheriv, scryptSync } from "node:crypto";
import { readFileSync } from "node:fs";
import { Client } from "/opt/nxeon/node_modules/ssh2/lib/index.js";
import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client/default.js";

// Load .env
const envTxt = readFileSync("/opt/nxeon/.env", "utf8");
for (const line of envTxt.split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}

function deriveKey() {
  return scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
}
function decryptSecret(enc) {
  if (!enc) return null;
  try {
    const [ivB64, tagB64, dataB64] = enc.split(":");
    if (!ivB64 || !tagB64 || !dataB64) return null;
    const d = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(ivB64, "base64"));
    d.setAuthTag(Buffer.from(tagB64, "base64"));
    return Buffer.concat([d.update(Buffer.from(dataB64, "base64")), d.final()]).toString("utf8");
  } catch {
    return null;
  }
}

const serverId = process.argv[2];
const expectedIp = process.argv[3];
const command = readFileSync(0, "utf8"); // stdin

const prisma = new PrismaClient();
const server = await prisma.server.findUnique({
  where: { id: serverId },
  include: { dedicatedIp: true },
});
await prisma.$disconnect();
if (!server) {
  console.error("SERVER_NOT_FOUND");
  process.exit(2);
}
const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
if (!password) {
  console.error("NO_PASSWORD");
  process.exit(3);
}
const dedicated = !!server.dedicatedIp;
const host = dedicated ? server.dedicatedIp.address : process.env.PUBLIC_IP || "";
const port = dedicated ? 22 : server.sshPort;

if (expectedIp && host !== expectedIp) {
  console.error(`HOST_MISMATCH expected=${expectedIp} got=${host}`);
  process.exit(4);
}

const conn = new Client();
conn
  .on("ready", () => {
    conn.exec(command, (err, stream) => {
      if (err) {
        console.error("EXEC_ERR", err.message);
        conn.end();
        process.exit(5);
      }
      stream
        .on("close", (code) => {
          conn.end();
          process.exit(code || 0);
        })
        .on("data", (d) => process.stdout.write(d))
        .stderr.on("data", (d) => process.stderr.write(d));
    });
  })
  .on("error", (e) => {
    console.error("SSH_ERR", e.message);
    process.exit(6);
  })
  .connect({ host, port, username: "root", password, readyTimeout: 20000 });

// pull/push files to .215 over SFTP using the decrypted server password.
// Usage:
//   node sftpio.mjs pull  <remoteAbsPath> <localAbsPath>
//   node sftpio.mjs push  <localAbsPath>  <remoteAbsPath>
//   node sftpio.mjs pulldir <remoteDir> <localDir> <globSuffixCsv>   (small trees)
import { createDecipheriv, scryptSync } from "node:crypto";
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import SftpClient from "/opt/nxeon/node_modules/ssh2-sftp-client/src/index.js";
import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client/default.js";

const envTxt = readFileSync("/opt/nxeon/.env", "utf8");
for (const line of envTxt.split("\n")) {
  const m = line.match(/^([A-Z0-9_]+)=(.*)$/);
  if (m && !process.env[m[1]]) process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
}
const deriveKey = () => scryptSync(process.env.AUTH_SECRET, "nxeon-byok", 32);
function decryptSecret(enc) {
  const [i, t, d] = enc.split(":");
  const dec = createDecipheriv("aes-256-gcm", deriveKey(), Buffer.from(i, "base64"));
  dec.setAuthTag(Buffer.from(t, "base64"));
  return Buffer.concat([dec.update(Buffer.from(d, "base64")), dec.final()]).toString("utf8");
}

const [op, a, b, c] = process.argv.slice(2);
const prisma = new PrismaClient();
const server = await prisma.server.findUnique({
  where: { id: "cmsecmdps0001hlp27ai6mr7c" },
  include: { dedicatedIp: true },
});
await prisma.$disconnect();
const password = decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
const host = server.dedicatedIp ? server.dedicatedIp.address : process.env.PUBLIC_IP;
const port = server.dedicatedIp ? 22 : server.sshPort;
if (host !== "51.79.226.215") { console.error("HOST_MISMATCH", host); process.exit(4); }

const sftp = new SftpClient();
await sftp.connect({ host, port, username: "root", password, readyTimeout: 20000 });
try {
  if (op === "pull") {
    const buf = await sftp.get(a);
    mkdirSync(dirname(b), { recursive: true });
    writeFileSync(b, buf);
    console.log("PULLED", a, "->", b, buf.length, "bytes");
  } else if (op === "push") {
    const buf = readFileSync(a);
    await sftp.put(buf, b);
    console.log("PUSHED", a, "->", b, buf.length, "bytes");
  } else if (op === "pulldir") {
    const suffixes = c.split(",");
    const list = await sftp.list(a); // shallow; caller loops for depth
    for (const e of list) {
      if (e.type === "-" && suffixes.some((s) => e.name.endsWith(s))) {
        const rp = `${a}/${e.name}`;
        const lp = `${b}/${e.name}`;
        const buf = await sftp.get(rp);
        mkdirSync(dirname(lp), { recursive: true });
        writeFileSync(lp, buf);
        console.log("  ", rp);
      }
    }
  } else {
    console.error("unknown op", op);
    process.exit(1);
  }
} finally {
  await sftp.end();
}

