        if (!input || !box) return;
        const apiEl = document.querySelector('[data-api-base]');
        const API = apiEl && apiEl.dataset ? (apiEl.dataset.apiBase || '') : '';
        const tok = () => localStorage.getItem('token') || '';
        const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
        const colors = ['#c8a45d','#4a90d9','#5cb85c','#d9534f','#8e5bd9','#d98c3f'];
        let timer = null, lastQ = '';

        function close() { box.classList.remove('open'); box.innerHTML = ''; }
        const ICO = {
          phone: '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.8 19.8 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.8 19.8 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.13.96.36 1.9.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0 1 22 16.92z"/></svg>',
