          search: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>',
          grp: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></svg>',
          pvt: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>',
          mat: '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="6" width="18" height="12" rx="2"/><path d="M3 12h18"/></svg>',
        };
        function render(list, q) {
          if (!list.length) { box.innerHTML = '<div class="cqs-empty">No clients found for “' + esc(q) + '”</div>'; box.classList.add('open'); return; }
          const total = list.length, shown = Math.min(4, total);
          const rows = list.slice(0, 4).map((c, i) => {
            const initials = (c.name || '?').split(' ').filter(Boolean).map(w => w[0]).join('').substring(0, 2).toUpperCase();
            const phone = [c.phoneCountryCode, c.phone].filter(Boolean).join(' ');
            const bits = [];
            if (phone) bits.push(ICO.phone + '<span>' + esc(phone) + '</span>');
            if (c.email) bits.push('<span class="sep">•</span>' + ICO.mail + '<span>' + esc(c.email) + '</span>');
            const contact = bits.length ? bits.join(' ') : '<span>No contact details</span>';
            return '<a class="cqs-item" href="/admin/client-profile?id=' + encodeURIComponent(c.id) + '">'
              + '<span class="cqs-av" style="background:' + colors[i % colors.length] + '">' + esc(initials) + '</span>'
              + '<div class="cqs-main"><div class="cqs-name">' + esc(c.name) + '</div><div class="cqs-contact">' + contact + '</div></div>'
              + '<div class="cqs-pkgs"><div class="lbl">Packages</div><div class="cqs-badges">'
              + '<span class="cqs-b grp">Group ' + (c.groupCredits || 0) + '</span>'
              + '<span class="cqs-b pvt">Private ' + (c.privateCredits || 0) + '</span>'
              + '<span class="cqs-b mat">Mat ' + (c.matCredits || 0) + '</span>'
              + '</div></div><span class="cqs-chev">' + ICO.chev + '</span></a>';
          }).join('');
          const head = '<div class="cqs-head"><span class="t">Top results</span><span class="n">Showing ' + shown + ' of ' + total + '</span></div>';
          const more = total > 4 ? '<a class="cqs-more" href="/admin/clients?search=' + encodeURIComponent(q) + '">' + ICO.search + ' View all ' + total + ' results →</a>' : '';
          const legend = '<div class="cqs-legend">'
            + '<div class="grp">' + ICO.grp + '<div><div class="lg-t">Group</div><div class="lg-d">Group classes</div></div></div>'
            + '<div class="pvt">' + ICO.pvt + '<div><div class="lg-t">Private</div><div class="lg-d">Private sessions</div></div></div>'
            + '<div class="mat">' + ICO.mat + '<div><div class="lg-t">Mat</div><div class="lg-d">Mat classes</div></div></div>'
            + '</div>';
          box.innerHTML = head + rows + more + legend;
          box.classList.add('open');
        }
        async function run(q) {
          try {
            const res = await fetch(API + '/api/client?sort=recent&search=' + encodeURIComponent(q), { headers: { Authorization: 'Bearer ' + tok() } });
            if (!res.ok) { close(); return; }
            const list = await res.json();
            if (q !== lastQ) return;
            render(Array.isArray(list) ? list : [], q);
          } catch (e) { close(); }
        }
        input.addEventListener('input', function () {
          const q = input.value.trim();
          lastQ = q;
          if (timer) clearTimeout(timer);
          if (q.length < 2) { close(); return; }
          timer = setTimeout(function () { run(q); }, 250);
        });
        input.addEventListener('focus', function () { if (input.value.trim().length >= 2 && box.innerHTML) box.classList.add('open'); });
        document.addEventListener('click', function (e) { if (wrap && !wrap.contains(e.target)) close(); });
        document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { close(); input.blur(); } });
      })();
    </script>
